// Docs index generator and checker. Schema and rules: docs/README.md.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"
import { parse as parseYaml } from "yaml"
import { z } from "zod"

export const MAX_LINES = 300
export const GENERATED =
  "<!-- Generated by `pnpm docs:index` from frontmatter. Do not edit. -->"

type SectionName = "" | "designs" | "backlogs"
type Section = {
  prefix: string
  title: string
  holds: string
  types: readonly string[]
  statuses: readonly string[]
}

export const SECTIONS: Record<SectionName, Section> = {
  "": {
    prefix: "DOC",
    title: "Guides",
    holds: "guides about the docs themselves",
    types: ["guide"],
    statuses: ["active"],
  },
  designs: {
    prefix: "DES",
    title: "Designs",
    holds: "system designs and UI instructions",
    types: ["design", "ui"],
    statuses: ["draft", "active", "deprecated"],
  },
  backlogs: {
    prefix: "BL",
    title: "Backlogs",
    holds: "chunked work items, one per file",
    types: ["backlog"],
    statuses: ["todo", "doing", "blocked", "done"],
  },
}

const id = z.string().regex(/^(DOC|DES|BL)-\d{3}$/, "must look like DES-001")
const base = {
  id,
  title: z.string().min(1),
  status: z.string(),
  summary: z
    .string()
    .min(1)
    .max(140)
    .refine((s) => !s.includes("\n"), "one line"),
  tags: z.array(z.string().regex(/^[a-z0-9-]+$/, "lowercase words")).min(1),
  related: z.array(id),
  updated: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "must be YYYY-MM-DD"),
}
export const frontmatterSchema = z.discriminatedUnion("type", [
  z.strictObject({ ...base, type: z.enum(["guide", "design", "ui"]) }),
  z.strictObject({
    ...base,
    type: z.literal("backlog"),
    priority: z.enum(["P0", "P1", "P2"]),
    depends: z.array(id),
  }),
])
export type Frontmatter = z.infer<typeof frontmatterSchema>
export type Doc = Frontmatter & { file: string; section: SectionName }

export type Result = { docs: Doc[]; errors: string[] }

function walk(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = join(dir, e.name)
    if (e.isDirectory()) return walk(p)
    return e.name.endsWith(".md") ? [p] : []
  })
}

export function countLines(text: string): number {
  return text.split("\n").length - (text.endsWith("\n") ? 1 : 0)
}

export function parseFrontmatter(
  text: string
): { ok: true; meta: Frontmatter } | { ok: false; errors: string[] } {
  const m = text.match(/^---\n([\s\S]*?)\n---\n/)
  if (!m) return { ok: false, errors: ["missing frontmatter"] }
  let raw: unknown
  try {
    raw = parseYaml(m[1])
  } catch (e) {
    return {
      ok: false,
      errors: [
        `frontmatter is not valid YAML: ${(e as Error).message.split("\n")[0]}`,
      ],
    }
  }
  const parsed = frontmatterSchema.safeParse(raw)
  if (parsed.success) return { ok: true, meta: parsed.data }
  return {
    ok: false,
    errors: parsed.error.issues.map(
      (i) => `${i.path.join(".") || "frontmatter"}: ${i.message}`
    ),
  }
}

// Every GFM table needs a header, a separator row, and equal column counts.
export function tableErrors(text: string): string[] {
  const errors: string[] = []
  const cols = (line: string) => line.replace(/\\\|/g, "").split("|").length - 2
  const lines = text.split("\n")
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i].startsWith("|") || (i > 0 && lines[i - 1].startsWith("|")))
      continue
    const want = cols(lines[i])
    const sep = lines[i + 1] ?? ""
    if (!/^\|( *:?-+:? *\|)+$/.test(sep) || cols(sep) !== want)
      errors.push(`table at line ${i + 1} has no valid separator row`)
    for (let j = i + 2; lines[j]?.startsWith("|"); j++)
      if (cols(lines[j]) !== want)
        errors.push(
          `table row at line ${j + 1} has ${cols(lines[j])} cells, want ${want}`
        )
  }
  return errors
}

export function loadDocs(docsDir: string): Result {
  const errors: string[] = []
  const root = dirname(docsDir)
  const fail = (file: string, msg: string) =>
    errors.push(`${relative(root, file)}: ${msg}`)
  const docs: Doc[] = []

  for (const file of walk(docsDir)) {
    const text = readFileSync(file, "utf8")
    const lines = countLines(text)
    if (lines > MAX_LINES) fail(file, `${lines} lines, max ${MAX_LINES}`)
    for (const [, target] of text.matchAll(/\]\(([^)\s]+)\)/g)) {
      if (/^[a-z]+:/.test(target) || target.startsWith("#")) continue
      if (!existsSync(resolve(dirname(file), target.split("#")[0])))
        fail(file, `broken link: ${target}`)
    }
    for (const e of tableErrors(text)) fail(file, e)

    const rel = relative(docsDir, file)
    if (rel === "INDEX.md" || rel.endsWith("/INDEX.md")) continue
    const parts = rel.split("/")
    const sectionName = (parts.length === 2 ? parts[0] : "") as SectionName
    const section = SECTIONS[sectionName]
    if (parts.length > 2 || !section) {
      fail(file, "docs live in docs/, docs/designs/ or docs/backlogs/ only")
      continue
    }
    const parsed = parseFrontmatter(text)
    if (!parsed.ok) {
      parsed.errors.forEach((e) => fail(file, e))
      continue
    }
    const meta = parsed.meta
    if (!meta.id.startsWith(`${section.prefix}-`))
      fail(file, `id must start with ${section.prefix}- in this folder`)
    if (
      rel !== "README.md" &&
      !parts.at(-1)!.startsWith(`${meta.id.toLowerCase()}-`)
    )
      fail(file, `file name must start with ${meta.id.toLowerCase()}-`)
    if (!section.types.includes(meta.type))
      fail(file, `type must be one of ${section.types.join(", ")}`)
    if (!section.statuses.includes(meta.status))
      fail(file, `status must be one of ${section.statuses.join(", ")}`)
    if (meta.type === "backlog" && !/^## Done when$/m.test(text))
      fail(file, 'backlog needs a "## Done when" section')
    docs.push({ ...meta, file, section: sectionName })
  }

  const byId = new Map<string, Doc>()
  for (const d of docs) {
    if (byId.has(d.id)) fail(d.file, `duplicate id ${d.id}`)
    byId.set(d.id, d)
  }
  for (const d of docs) {
    for (const r of d.related)
      if (!byId.has(r)) fail(d.file, `related ${r} not found`)
    if (d.type === "backlog")
      for (const r of d.depends)
        if (byId.get(r)?.type !== "backlog")
          fail(d.file, `depends ${r} is not a backlog`)
  }
  return { docs, errors }
}

const cell = (s: string) => s.replaceAll("|", "\\|")
const link = (d: Doc, from: string) =>
  `[${cell(d.title)}](${relative(from, d.file)})`
const inSection = (docs: Doc[], name: SectionName) =>
  docs
    .filter((d) => d.section === name)
    .sort((a, b) => a.id.localeCompare(b.id))

function sectionIndex(
  docs: Doc[],
  docsDir: string,
  name: "designs" | "backlogs"
): string {
  const s = SECTIONS[name]
  const dir = join(docsDir, name)
  const rows = inSection(docs, name).map((d) =>
    d.type === "backlog"
      ? `| ${d.id} | ${d.status} | ${d.priority} | ${d.depends.join(", ") || "-"} | ${link(d, dir)} | ${cell(d.summary)} | ${d.tags.join(", ")} |`
      : `| ${d.id} | ${d.type} | ${d.status} | ${link(d, dir)} | ${cell(d.summary)} | ${d.tags.join(", ")} |`
  )
  const head =
    name === "backlogs"
      ? "| ID | Status | Pri | Depends | Title | Summary | Tags |\n| --- | --- | --- | --- | --- | --- | --- |"
      : "| ID | Type | Status | Title | Summary | Tags |\n| --- | --- | --- | --- | --- | --- |"
  return `${GENERATED}\n\n# ${s.title} index\n\nHolds ${s.holds}. Back to [docs index](../INDEX.md).\n\n${head}\n${rows.join("\n")}\n`
}

function rootIndex(docs: Doc[], docsDir: string): string {
  const sections = (["designs", "backlogs"] as const).map((n) => {
    const rows = inSection(docs, n)
    const open =
      n === "backlogs"
        ? `, ${rows.filter((d) => d.status !== "done").length} open`
        : ""
    return `| ${SECTIONS[n].title} | [${n}/INDEX.md](${n}/INDEX.md) | ${rows.length} docs${open} | ${SECTIONS[n].holds} |`
  })
  const guides = inSection(docs, "").map(
    (d) => `| ${d.id} | ${link(d, docsDir)} | ${cell(d.summary)} |`
  )
  return [
    GENERATED,
    "",
    "# Docs index",
    "",
    "Start here. Then open one section index, then only the doc you need.",
    "Schema and retrieval rules: [README.md](README.md).",
    "",
    "| Section | Index | Size | Holds |",
    "| --- | --- | --- | --- |",
    ...sections,
    "",
    "| ID | Guide | Summary |",
    "| --- | --- | --- |",
    ...guides,
    "",
  ].join("\n")
}

// Indexes are emitted unpadded and skip prettier (see .prettierignore and DES-007).
export function renderIndexes(
  docs: Doc[],
  docsDir: string
): Record<string, string> {
  return {
    [join(docsDir, "INDEX.md")]: rootIndex(docs, docsDir),
    [join(docsDir, "designs", "INDEX.md")]: sectionIndex(
      docs,
      docsDir,
      "designs"
    ),
    [join(docsDir, "backlogs", "INDEX.md")]: sectionIndex(
      docs,
      docsDir,
      "backlogs"
    ),
  }
}

export function run(docsDir: string, mode: "check" | "index"): Result {
  const result = loadDocs(docsDir)
  const root = dirname(docsDir)
  for (const [file, text] of Object.entries(
    renderIndexes(result.docs, docsDir)
  )) {
    if (mode === "index") writeFileSync(file, text)
    else if (!existsSync(file) || readFileSync(file, "utf8") !== text)
      result.errors.push(
        `${relative(root, file)}: stale, run \`pnpm docs:index\``
      )
  }
  return result
}
